sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var body = request.body.data;
        var gr = new GlideRecord('u_custom_form_data'); // Your actual table

        // Check if a record with the same user_id already exists
        gr.addQuery('u_created_by', body.user_id);
        gr.query();

        if (gr.next()) {
            // ✅ Existing record found - Perform update
            gr.setValue('u_procurement_system', body.procurement);
            gr.setValue('u_cloud_discovery', body.cloudDiscovery);
            gr.setValue('u_third_party_software', body.thirdPartySoftware);
            gr.setValue('u_third_party_software_name', body.thirdPartyName);
            gr.setValue('u_client_software', body.clientSoftware);
            gr.setValue('u_integration_type', body.clientSoftwareIntegration);

            var updated = gr.update(); // Returns sys_id of the updated record

            if (updated) {
                response.setStatus(200);
                response.setBody({
                    message: "✅ Data updated successfully!",
                    sys_id: gr.sys_id
                });
            } else {
                throw new Error("Update operation failed.");
            }
        } else {
            // ❌ No record found - Perform insert
            gr.initialize();
            gr.setValue('u_created_by', body.user_id);
            gr.setValue('u_procurement_system', body.procurement);
            gr.setValue('u_cloud_discovery', body.cloudDiscovery);
            gr.setValue('u_third_party_software', body.thirdPartySoftware);
            gr.setValue('u_third_party_software_name', body.thirdPartyName);
            gr.setValue('u_client_software', body.clientSoftware);
            gr.setValue('u_integration_type', body.clientSoftwareIntegration);

            var recordID = gr.insert();

            if (recordID) {
                response.setStatus(201);
                response.setBody({
                    message: "✅ Data submitted successfully!",
                    sys_id: recordID
                });
            } else {
                throw new Error("Insert operation failed.");
            }
        }
    } catch (err) {
        response.setStatus(500);
        response.setBody({ error: "❌ Server error: " + err.message });
    }
})(request, response);
